package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.util.Annotations;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.reflect.Proxy;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnnotationMap__add_TriageGen0Test {

    private AnnotationMap annotationMap;

    @Before
    public void setUp() {
        annotationMap = new AnnotationMap();
    }

    /**
     * Helper to create a mock Annotation instance using Proxy.
     */
    @SuppressWarnings("unchecked")
    private <T extends Annotation> T createMockAnnotation(Class<T> type) {
        return (T) Proxy.newProxyInstance(
                type.getClassLoader(),
                new Class[]{type},
                (proxy, method, args) -> {
                    if (method.getName().equals("annotationType")) {
                        return type;
                    }
                    if (method.getName().equals("equals")) {
                        return proxy == args[0];
                    }
                    return null;
                });
    }

    @Retention(RetentionPolicy.RUNTIME)
    @interface TestAnnotationA {}

    @Retention(RetentionPolicy.RUNTIME)
    @interface TestAnnotationB {}

    @Test
    public void testAdd_FirstTime_ReturnsFalse() {
        TestAnnotationA ann = createMockAnnotation(TestAnnotationA.class);

        // First add should return false because previous was null
        boolean result = annotationMap.add(ann);

        assertFalse("First addition should return false", result);
        assertEquals("Size should be 1", 1, annotationMap.size());
    }

    @Test
    public void testAdd_DuplicateExactInstance_ReturnsTrue() {
        TestAnnotationA ann = createMockAnnotation(TestAnnotationA.class);

        annotationMap.add(ann);
        // Adding the exact same instance again
        boolean result = annotationMap.add(ann);

        assertTrue("Adding the exact same instance should return true", result);
        assertEquals("Size should still be 1", 1, annotationMap.size());
    }

    @Test
    public void testAdd_DifferentInstanceSameTypeSameEquals_ReturnsTrue() {
        // We need to simulate an annotation that is 'equal' but not the same instance
        // The implementation uses previous.equals(ann)

        class EqualAnnotation implements TestAnnotationA {
            private final boolean equal;
            EqualAnnotation(boolean equal) { this.equal = equal; }
            @Override public Class<? extends Annotation> annotationType() { return TestAnnotationA.class; }
            @Override public boolean equals(Object obj) {
                if (obj instanceof EqualAnnotation) return this.equal == ((EqualAnnotation) obj).equal;
                return false;
            }
            @Override public int hashCode() { return 1; }
        }

        EqualAnnotation ann1 = new EqualAnnotation(true);
        EqualAnnotation ann2 = new EqualAnnotation(true);
        EqualAnnotation ann3 = new EqualAnnotation(false);

        annotationMap.add(ann1);

        // Case 1: Same type, same equality
        assertTrue("Should return true for logically equal annotation", annotationMap.add(ann2));

        // Case 2: Reset map for different test logic
        annotationMap = new AnnotationMap();
        annotationMap.add(ann1);
        // Case 3: Same type, different equality
        assertFalse("Should return false for non-equal annotation of same type", annotationMap.add(ann3));
    }

    @Test
    public void testAdd_DifferentAnnotationTypes_ReturnsFalse() {
        TestAnnotationA annA = createMockAnnotation(TestAnnotationA.class);
        TestAnnotationB annB = createMockAnnotation(TestAnnotationB.class);

        annotationMap.add(annA);
        boolean result = annotationMap.add(annB);

        assertFalse("Adding a different type should return false", result);
        assertEquals("Size should be 2", 2, annotationMap.size());
    }

    @Test
    public void testAdd_NullAnnotation_ThrowsException() {
        try {
            annotationMap.add(null);
            fail("Should have thrown NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }
}
